(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const back = Array.from(document.querySelectorAll('a,button,div,span')).find(e => /back/i.test((e.innerText||'').replace(/\s+/g,' ').trim()) && (e.innerText||'').replace(/\s+/g,' ').trim().length < 8 && e.offsetParent!==null);
  let hit = '';
  if (back) { back.click(); hit = (back.innerText||'').replace(/\s+/g,' ').trim(); }
  await sleep(2500);
  // scroll right panel to top
  document.querySelectorAll('*').forEach(e => { if (e.scrollHeight > e.clientHeight && e.clientHeight > 200 && e.offsetTop < 200) { /* best-effort scroll */ } });
  window.scrollTo(0,0);
  return JSON.stringify({hit, url: location.href});
})()
